package dk.stream.android;

import okhttp3.HttpUrl;
import org.junit.Test;
import static org.junit.Assert.*;

public class PcloudAccountTest {
 @Test public void credentialsRoundTripInsideLibraryWithoutChangingOtherSettings() throws Exception {Library library=new Library();library.favoritesOnStart=true;library.setFavoritesStartTab(1);library.pcloud=new PcloudAccount(PcloudAccount.EU,"person@example.com","test-secret");Library restored=Library.fromJson(library.toJson());assertEquals("test-secret",restored.pcloud.password);assertEquals(library.pcloud.id,restored.pcloud.id);assertTrue(restored.favoritesOnStart);assertEquals(1,restored.favoritesStartTab);}
 @Test public void oldLibrariesHaveNoCloudLogin() throws Exception {assertNull(Library.fromJson(new Library().toJson()).pcloud);}
 @Test public void loginCanOnlyTargetTheTwoSecurePcloudEndpoints(){for(String endpoint:new String[]{"http://ewebdav.pcloud.com/","https://evil.example/","https://ewebdav.pcloud.com.evil.example/","https://user:password@ewebdav.pcloud.com/","https://ewebdav.pcloud.com:8443/","https://ewebdav.pcloud.com/path/"})try{new PcloudAccount(endpoint,"person@example.com","secret");fail(endpoint);}catch(IllegalArgumentException expected){}}
 @Test public void documentReferencesHaveNoCredentialsAndSurviveLoginAgain(){PcloudAccount first=new PcloudAccount(PcloudAccount.EU,"person@example.com","old-password"),next=new PcloudAccount(PcloudAccount.EU,"person@example.com","new-password");String ref=PcloudDocument.uri(first,HttpUrl.get(PcloudAccount.EU+"Music/S%C3%B8ndag%20%26%20venner.mp3"),42);assertFalse(ref.contains(first.email));assertFalse(ref.contains(first.password));assertEquals(42,PcloudDocument.size(ref));assertEquals("/Music/Søndag & venner.mp3",PcloudDocument.url(next,ref).uri().getPath());}
 @Test public void anotherAccountCannotResolveSavedLinks(){PcloudAccount first=new PcloudAccount(PcloudAccount.EU,"first@example.com","first"),second=new PcloudAccount(PcloudAccount.EU,"second@example.com","second");String ref=PcloudDocument.uri(first,HttpUrl.get(first.server+"song.mp3"),1);try{PcloudDocument.url(second,ref);fail();}catch(IllegalArgumentException expected){}try{PcloudDocument.url(null,ref);fail();}catch(IllegalArgumentException expected){}}
 @Test public void tamperedDocumentCannotSendCredentialsElsewhere(){PcloudAccount account=new PcloudAccount(PcloudAccount.EU,"person@example.com","secret");try{PcloudDocument.uri(account,HttpUrl.get("https://evil.example/song.mp3"),1);fail();}catch(IllegalArgumentException expected){}String bad="content://"+PcloudDocument.AUTHORITY+"/"+account.id+"?url=https%3A%2F%2Fevil.example%2Fsong.mp3";try{PcloudDocument.url(account,bad);fail();}catch(IllegalArgumentException expected){}}
 @Test public void loggedOutBookmarksKeepTheirStableIdentity() throws Exception {Library library=new Library();PcloudAccount account=new PcloudAccount(PcloudAccount.US,"person@example.com","secret");library.pcloud=account;LocalMedia song=new LocalMedia(PcloudDocument.uri(account,HttpUrl.get(account.server+"song.mp3"),10),"song.mp3","audio/mpeg",false);library.toggleLocalFavorite(song);library.pcloud=null;Library restored=Library.fromJson(library.toJson());assertNull(restored.pcloud);assertTrue(restored.isLocalFavorite(song.uri));assertTrue(song.audio());}
}
